import {facts} from './facts-bank.js';
import {isAdmin} from './admin.js';
import {aiReady,askAI,aiError} from './ai-client.js';
import {tracks,makeLevel,chapterTitle} from './game-content.js';
import {icon3D as I} from './icons.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='zuno-games-v1';let records={},saveOK=true;try{records=JSON.parse(localStorage.getItem(KEY)||'{}');if(!records||Array.isArray(records)||typeof records!=='object')records={}}catch{records={};saveOK=false}
let session=null,ctx=null,activeChapter=0;
const validScore=x=>Number.isInteger(x)&&x>=1&&x<=3;
const key=(id,age,l)=>`${age}:${id}:${l}`;
export const gamePoints=()=>Object.entries(records).filter(([k,v])=>/^(6-8|9-11|12-14):(math|patterns|english|kiswahili|crossword|memory|science|code):([1-9][0-9]?|100)$/.test(k)&&validScore(v)).reduce((n,[,v])=>n+v*5,0);
export function clearGames(){records={};session=null;try{localStorage.removeItem(KEY)}catch{}}
const saved=(id,age,l)=>validScore(records[key(id,age,l)])?records[key(id,age,l)]:0;
const completed=(id,age)=>Array.from({length:100},(_,i)=>saved(id,age,i+1)).filter(Boolean).length;
const nextLevel=(id,age)=>Array.from({length:100},(_,i)=>i+1).find(l=>!saved(id,age,l))||100;
const sticker=t=>I(({math:"calculator",patterns:"puzzle",english:"alphabet",kiswahili:"book-open",crossword:"crossword",memory:"memory",code:"rover",science:"lightbulb"})[t.id],"game-sticker");
export function arcade(age){const factIndex=Math.floor(Date.now()/86400000)%facts.length,dailyFact=facts[factIndex];const total=tracks.reduce((n,t)=>n+completed(t.id,age),0);return `<section class="arcade"><div class="arcade-heading"><span class="eyebrow">ZUNO PLAY · AGES ${age}</span><h1>Little moves.<br><em>Big brain energy.</em></h1><p>Pick a world. Follow a path. Surprise yourself.</p></div><div class="play-welcome"><img src="/assets/zuno-icon.webp" alt="Zuno"><div><strong>Your next “I did it!” starts here.</strong><p>${total?`${total} levels explored. What shall we try next?`:'No timer. Plenty of chances. Let’s play with an idea.'}</p></div><span class="play-welcome-star">${I('star')}</span></div><a class="fact-play-banner" href="#/play/facts/${factIndex+1}">${I('lightbulb')}<div><span class="eyebrow">DID YOU KNOW?</span><h2>${esc(dailyFact.title)}</h2><p>${esc(dailyFact.levels[age])}</p><span class="text-link">Explore 300 little wonders ${I('arrow-right')}</span></div></a><div class="arcade-grid">${tracks.map(t=>{const n=completed(t.id,age),next=nextLevel(t.id,age);return `<a href="#/play/${t.id}/map" class="arcade-card tone-${t.color}"><div class="arcade-art">${sticker(t)}<span class="game-count">100 levels</span></div><div class="arcade-card-copy"><h2>${t.title}</h2><p>${t.description}</p><div class="arcade-progress"><span style="width:${n}%"></span></div><div class="arcade-meta"><span>${n}/100 explored</span><span class="raised-mini">${n?'Continue':'Let’s play'} ${I('arrow-right')}</span></div></div></a>`}).join('')}</div><div class="play-extras"><a class="play-extra" href="#/play/facts/1">${I('lightbulb')}<div><strong>Did You Know?</strong><span>300 discoveries · three age editions · a new reason to wonder.</span></div>${I('arrow-right')}</a><a class="play-extra" href="#/play/cube/1">${I('puzzle')}<div><strong>ZUNO Cube Lab</strong><span>Twist. Notice. Solve. 20 challenges for your reading band.</span></div>${I('arrow-right')}</a><a class="play-extra" href="#/play/code/map">${I('code-2')}<div><strong>Rover Code Lab</strong><span>Build. Test. Debug your own route.</span></div>${I('arrow-right')}</a><a class="play-extra" href="#/explore">${I('orbit')}<div><strong>More ways to wonder</strong><span>Explore worlds and hands-on virtual labs.</span></div>${I('arrow-right')}</a></div><p class="game-small-print">100 practice levels per game and reading band. New combinations build on earlier skills; vocabulary and discovery ideas return for useful practice.</p></section>`}
export function levelMap(id,age,chapter){const t=tracks.find(t=>t.id===id);if(!t)return '';const next=nextLevel(id,age);activeChapter=Number.isInteger(chapter)&&chapter>=0&&chapter<10?chapter:Math.floor((next-1)/10);const start=activeChapter*10+1,done=completed(id,age);return `<section class="level-map tone-${t.color}"><div class="map-toolbar"><a class="chip" href="#/play">${I('arrow-left')}Games</a><span>${I('star')}${done}/100 explored</span><button class="chip icon-button" data-action="age" aria-label="Change reading level">${I('settings-2')}</button></div><div class="map-banner"><div><span class="eyebrow">${t.title} · Ages ${age}</span><h1>Chapter ${activeChapter+1}</h1><p>${chapterTitle(id,start,age)}</p></div>${sticker(t)}</div><div class="chapter-controls"><a class="chip ${activeChapter===0?'unavailable':''}" ${activeChapter===0?'aria-disabled="true"':`href="#/play/${id}/map?chapter=${activeChapter-1}"`}>${I('arrow-left')}Earlier</a><span>${start}–${start+9} of 100</span><a class="chip ${activeChapter===9?'unavailable':''}" ${activeChapter===9?'aria-disabled="true"':`href="#/play/${id}/map?chapter=${activeChapter+1}"`}>Next${I('arrow-right')}</a></div><div class="path-layout"><div class="game-path">${Array.from({length:10},(_,i)=>{const l=start+i,s=saved(id,age,l),current=l===next,locked=l>next&&!isAdmin();return `<div class="level-stop stop-${i%4} ${current?'current':''}"><a ${locked?'aria-disabled="true" tabindex="-1"':`href="#/play/${id}/${l}"`} class="level-node ${locked?'level-locked':''} ${s?'level-done':''}" aria-label="Level ${l}${s?`, ${s} stars earned`:''}${current?', suggested next':''}">${I(locked?'lock-keyhole':s?'check':l%10===0?'trophy':'play')}<span>${l}</span></a><div class="level-caption">${current?'<strong>Try this one!</strong>':s?`<strong>${'★'.repeat(s)}</strong>`:`${locked?'Locked · ':''}Level ${l}`}</div></div>`}).join('')}<div class="chapter-prize">${I('chest')}<strong>${Array.from({length:10},(_,i)=>saved(id,age,start+i)).every(Boolean)?'Chapter badge earned!':'A chapter of discoveries'}</strong><p>Explore these ten levels to earn your chapter badge.</p></div></div><aside class="path-guide"><img src="/assets/zuno-icon.webp" alt="Zuno"><h2>Small steps add up.</h2><p>Finish each level to unlock the next. You can revisit any level you have already unlocked.</p><a class="button" href="#/play/${id}/${next}">Level ${next} ${I('play')}</a><small>Your progress is saved on this browser, separately for each reading band.</small></aside></div></section>`}
function header(t,s,progress){return `<div class="game-session-top"><a class="chip icon-button" href="#/play/${t.id}/map?chapter=${Math.floor((s.level-1)/10)}" aria-label="Leave level and view path">${I('x')}</a><div class="session-progress"><span style="width:${progress}%"></span></div><button class="chip icon-button" data-game="settings" aria-label="Game sound and vibration settings">${I('settings-2')}</button></div><div class="game-level-caption">${esc(t.title)} · Level ${s.level} · Ages ${s.age}</div>`}
function stars(n){return `<div class="earned-stars" aria-label="${n} out of 3 stars">${[1,2,3].map(v=>`<span class="${v<=n?'earned':'unearned'}">${I('star')}</span>`).join('')}</div>`}
export function gamePage(id,level,age,science){const t=tracks.find(t=>t.id===id);if(!t||!Number.isInteger(level)||level<1||level>100)return `<div class="empty"><h1>Let’s find your path.</h1><a class="button" href="#/play">Choose a game</a></div>`;
 if(level>nextLevel(id,age)&&!isAdmin())return `<div class="empty"><h1>This discovery is still locked.</h1><p>Finish level ${nextLevel(id,age)} first to unlock the next step.</p><a class="button" href="#/play/${id}/${nextLevel(id,age)}">Continue level ${nextLevel(id,age)}</a></div>`;
 if(!session||session.id!==id||session.level!==level||session.age!==age)session={id,level,age,data:makeLevel(id,level,age,science),index:0,selected:null,checked:false,score:0,attempts:0,done:false,entries:{},flipped:[],matched:[],moves:0,hints:0,active:null,revealed:false,program:[],rover:null,codeMessage:''};
 const s=session;if(s.done)return `<section class="game-session tone-${t.color}">${header(t,s,100)}<div class="level-celebration"><div class="reward-orbit">${I('prize')}</div><span class="eyebrow">LEVEL ${level} EXPLORED</span><h1>${s.stars===3?'Look at you glow!':s.stars===2?'Your ideas are growing!':'That’s a new discovery!'}</h1><p>${s.data.kind==='questions'?`${s.score} of ${s.data.questions.length} right on your first try. `:''}You made time for a little thinking. Nice work.</p>${stars(s.stars)}<div class="result-stats"><div><strong>${s.stars*5}</strong><span>best-level points</span></div><div><strong>${completed(id,age)}</strong><span>levels explored</span></div></div>${s.newPoints>0?`<div class="earned-points">+${s.newPoints} curiosity points added</div>`:'<p class="game-small-print">Your best stars are already saved. Practice is always welcome.</p>'}<div class="game-result-actions">${level<100?`<a class="button" href="#/play/${id}/${level+1}">Next level ${I('arrow-right')}</a>`:`<a class="button" href="#/play/${id}/map">All 100 explored ${I('trophy')}</a>`}<a class="chip" href="#/play/${id}/map?chapter=${Math.floor((level-1)/10)}">Back to my path</a><button class="text-link" data-game="replay">Play this level again</button></div></div></section>`;
 let body='',progress=0;if(s.data.kind==='questions'){const q=s.data.questions[s.index];progress=s.index/s.data.questions.length*100;body=`<div class="challenge-mascot"><img src="/assets/zuno-icon.webp" alt=""><span>${s.index===0?'Let’s work this one out.':s.score===s.index?'You’re connecting the dots!':'Every try teaches you something.'}</span></div><div class="challenge-number">Question ${s.index+1} of ${s.data.questions.length}</div><h1 class="challenge-title" tabindex="-1">${esc(q.q)}</h1><div class="answer-tiles" role="group" aria-label="Choose an answer">${q.options.map((o,i)=>`<button class="answer-tile ${s.selected===i?'selected':''} ${s.checked&&i===q.correct?'answer-right':''} ${s.checked&&s.selected===i&&i!==q.correct?'answer-wrong':''}" data-game-option="${i}" aria-pressed="${s.selected===i}" ${s.checked?'disabled':''}><span class="answer-letter">${String.fromCharCode(65+i)}</span><span>${esc(o)}</span>${s.checked&&i===q.correct?I('check'):''}</button>`).join('')}</div><div class="game-feedback ${s.checked?(s.selected===q.correct?'positive':'try-again'):''}" role="status">${s.checked?`<div>${I(s.selected===q.correct?'star':'lightbulb')}<strong>${s.selected===q.correct?'That clicks!':'Here’s the idea.'}</strong></div><p>${esc(q.why)}</p>`:''}</div><div class="session-actions"><button class="button" data-game="${s.checked?'next':'check'}" ${!s.checked&&s.selected===null?'disabled':''}>${s.checked?(s.index===s.data.questions.length-1?'Finish level':'Continue'):'Check answer'} ${I(s.checked?'arrow-right':'sparkles')}</button></div>`}
 else if(s.data.kind==='memory'){progress=s.matched.length/s.data.cards.length*100;body=`<h1 class="challenge-title" tabindex="-1">A little memory magic.</h1><p class="challenge-instruction">Turn over two tiles. Find every matching pair.</p><div class="memory-stats"><span>${s.matched.length/2}/${s.data.pairs} pairs</span><span>${s.moves} turns</span></div><div class="memory-board">${s.data.cards.map((n,i)=>{const visible=s.flipped.includes(i)||s.matched.includes(i);return `<button class="memory-tile ${visible?'turned':''} ${s.matched.includes(i)?'matched':''}" data-memory="${i}" ${s.matched.includes(i)||s.flipped.includes(i)?'disabled':''} aria-label="Tile ${i+1}${visible?', '+(['compass','','planet','controller','star','book'][n]||'symbol '+n):', face down'}">${visible?`<span class="icon zuno-3d-icon i3d-${n}" aria-hidden="true"></span>`:I('sparkles')}</button>`}).join('')}</div><div class="game-feedback" role="status">${s.flipped.length===2?'<p>Different tiles. Notice their places, then try another pair.</p>':s.memoryMessage?'<p>'+s.memoryMessage+'</p>':''}</div>${s.flipped.length===2?'<button class="button light" data-game="turn-back">Turn these back</button>':''}`}
 else if(s.data.kind==='code'){const p=s.data,position=s.rover??p.start;progress=0;body=`<h1 class="challenge-title" tabindex="-1">Give your rover a plan.</h1><p class="challenge-instruction">Add steps, then run your program. Reach the star and avoid the blocks. A shortest route takes ${p.target} steps.</p><div class="rover-board" style="--size:${p.size}">${Array.from({length:p.size*p.size},(_,i)=>`<div class="rover-cell ${p.blocked.includes(i)?'blocked':''}">${i===position?'<img src="/assets/zuno-icon.webp" alt="Rover">':i===p.goal?I('star'):p.blocked.includes(i)?'<span class="rover-rock" aria-label="Block"></span>':''}</div>`).join('')}</div><div class="rover-pad" aria-label="Add a movement instruction">${[['up','Up',-90],['right','Right',0],['down','Down',90],['left','Left',180]].map(([d,label,rot])=>`<button class="chip" data-rover-step="${d}" aria-label="Add ${label.toLowerCase()} step"><span style="transform:rotate(${rot}deg);display:inline-flex">${I('arrow-right')}</span><small>${label}</small></button>`).join('')}</div><div class="rover-program" aria-label="Your program">${s.program.length?s.program.map((d,i)=>`<button class="rover-instruction" data-rover-remove="${i}" aria-label="Remove step ${i+1}: ${d}"><span style="display:inline-flex;transform:rotate(${({up:-90,right:0,down:90,left:180})[d]}deg)">${I('arrow-right')}</span><small>${i+1}</small></button>`).join(''):'<p>Your instructions will collect here.</p>'}</div><div class="game-feedback" role="status"><p>${s.codeMessage||'What route can you see? Tap any instruction to remove it.'}</p></div><div class="crossword-actions"><button class="chip" data-game="reset-rover">${I('rotate-ccw')}Reset</button><button class="button" data-game="run-rover" ${!s.program.length?'disabled':''}>Run program ${I('play')}</button></div>`}
 else {const p=s.data.puzzle;progress=Object.values(s.entries).filter(Boolean).length/p.cells.length*100;const active=s.active? p.entries.find(e=>`${e.number}${e.dir}`===s.active):null;body=`<h1 class="challenge-title" tabindex="-1">Words that meet.</h1><p class="challenge-instruction">Tap a clue. Type its word; crossing letters help.</p><div class="crossword-layout"><div class="crossword-board" style="--columns:${p.width};--rows:${p.height}">${Array.from({length:p.width*p.height},(_,i)=>{let x=i%p.width,y=Math.floor(i/p.width),cell=p.cells.find(c=>c.x===x&&c.y===y),value=s.entries[`${x},${y}`]||'';return cell?`<div class="cross-cell ${s.checked?(value===cell.answer?'cell-right':'cell-wrong'):''}">${cell.number?`<small>${cell.number}</small>`:''}<input data-cross-cell="${x},${y}" maxlength="1" value="${esc(value)}" aria-label="Row ${y+1}, column ${x+1}${cell.number?', clue '+cell.number:''}" autocomplete="off" autocapitalize="characters" spellcheck="false"></div>`:'<div class="cross-block" aria-hidden="true"></div>'}).join('')}</div><div class="cross-clues">${['a','d'].map(dir=>`<div><h2>${dir==='a'?'Across':'Down'}</h2>${p.entries.filter(e=>e.dir===dir).map(e=>`<button data-cross-clue="${e.number}${e.dir}" class="${s.active===`${e.number}${e.dir}`?'active':''}"><strong>${e.number}.</strong> ${esc(e.clue)} <span>(${e.word.length})</span></button>`).join('')}</div>`).join('')}</div></div><div class="crossword-entry"><label for="cross-answer">${active?`${active.number} ${active.dir==='a'?'Across':'Down'} · ${active.word.length} letters`:'Choose a clue above'}</label><div><input id="cross-answer" name="answer" autocomplete="off" autocapitalize="characters" spellcheck="false" placeholder="Type a whole word" ${!active?'disabled':''}><button class="chip" data-game="place-word" ${!active?'disabled':''}>Place word</button></div></div><div class="game-feedback ${s.checked?'try-again':''}" role="status">${s.checked?'<p>Some letters need another look. Correct letters stay highlighted.</p>':s.hintMessage?`<p>${esc(s.hintMessage)}</p>`:''}</div><div class="crossword-actions"><button class="chip" data-game="hint">${I('lightbulb')}Letter hint</button><button class="button" data-game="check-crossword">Check puzzle ${I('sparkles')}</button></div>`}
 return `<section class="game-session tone-${t.color}">${header(t,s,progress)}<div class="challenge-surface">${body}${s.data.kind==='questions'?`<button class="chip game-ai-hint" data-game="ai-hint">${I('lightbulb')}Ask Zuno for a hint</button>`:''}</div></section>`}
export function mountGames({age,render,toast,reduced,onComplete,science}){ctx={age,render,toast,reduced,onComplete,science};}
function saveResult(stars){const s=session;if(!s||s.done)return;const k=key(s.id,s.age,s.level),old=saved(s.id,s.age,s.level);records[k]=Math.max(old,stars);s.stars=stars;s.newPoints=Math.max(0,stars-old)*5;s.done=true;try{localStorage.setItem(KEY,JSON.stringify(records))}catch{saveOK=false;ctx.toast('This browser cannot save game progress. You can still play.')}ctx.onComplete?.();feedback(true,true);ctx.render(false)}
let sound=false,haptics=true;try{sound=localStorage.getItem('zuno-game-sound')==='on';haptics=localStorage.getItem('zuno-game-haptics')!=='off'}catch{}
export function feedback(positive,celebrate=false){if(!ctx)return;if(haptics&&!ctx.reduced()&&typeof navigator.vibrate==='function')try{navigator.vibrate(positive?[18,35,18]:12)}catch{}if(sound){try{const AC=window.AudioContext||window.webkitAudioContext,a=new AC(),o=a.createOscillator(),g=a.createGain();o.connect(g);g.connect(a.destination);o.frequency.setValueAtTime(positive?660:330,a.currentTime);o.frequency.exponentialRampToValueAtTime(positive?990:294,a.currentTime+.12);g.gain.setValueAtTime(.055,a.currentTime);g.gain.exponentialRampToValueAtTime(.001,a.currentTime+.25);o.start();o.stop(a.currentTime+.26);o.onended=()=>a.close()}catch{}}if(celebrate&&!ctx.reduced()&&window.confetti)window.confetti({particleCount:65,spread:65,origin:{y:.65},colors:['#1E3DFF','#00CDE8','#A8FF00','#FF3ACB','#FFB800'],disableForReducedMotion:true});}
export function handleGameClick(e){const b=e.target.closest('button');if(!b||!ctx)return false;const s=session;if(b.dataset.gameOption!==undefined&&s&&!s.checked){s.selected=Number(b.dataset.gameOption);ctx.render(false);return true}
 if(b.dataset.memory!==undefined&&s){const i=Number(b.dataset.memory);if(s.flipped.length>=2||s.matched.includes(i)||s.flipped.includes(i))return true;s.flipped.push(i);if(s.flipped.length===2){s.moves++;const [a,b]=s.flipped;if(s.data.cards[a]===s.data.cards[b]){s.matched.push(a,b);s.flipped=[];s.memoryMessage='A match! Your memory made a connection.';feedback(true);if(s.matched.length===s.data.cards.length){saveResult(s.moves<=s.data.pairs+2?3:s.moves<=s.data.pairs*2?2:1);return true}}}ctx.render(false);return true}
 if(b.dataset.crossClue&&s){s.active=b.dataset.crossClue;ctx.render(false);document.querySelector('#cross-answer')?.focus();return true}
 if(b.dataset.roverStep&&s){if(s.program.length>=s.data.target+14){ctx.toast('Your program is full. Remove a step or reset it.');return true}s.program.push(b.dataset.roverStep);s.rover=s.data.start;s.codeMessage='Ready to test your instructions?';ctx.render(false);return true}if(b.dataset.roverRemove!==undefined&&s){s.program.splice(Number(b.dataset.roverRemove),1);s.rover=s.data.start;ctx.render(false);return true}
 const a=b.dataset.game;if(!a)return false;e.preventDefault();if(a==='ai-hint'&&s){const q=s.data.questions?.[s.index];if(q){const d=document.querySelector('#settings');d.innerHTML=`<button class="close" data-action="close-dialog" aria-label="Close learning hint">${I('x')}</button><h2>A little nudge.</h2><div class="ai-hint-body" role="status">Finding a checked hint…</div>`;d.showModal();const target=d.querySelector('.ai-hint-body');askAI({question:('Give a learning hint without revealing the answer: '+q.q).slice(0,600),ageBand:s.age,task:'hint'}).then(r=>{if(target.isConnected)target.innerHTML=`<p>${esc(r.answer)}</p>${(r.sources||[]).map(x=>`<a class="text-link" href="${esc(x.url)}" target="_blank" rel="noopener noreferrer" data-external="true">${esc(x.title)}</a>`).join('')}<p class="reading-level">AI checks can miss errors. Ask a grown-up if unsure.</p>`}).catch(e=>{if(target.isConnected)target.textContent=aiError(e.code)})}return true}if(a==='settings'){const d=document.querySelector('#settings');d.innerHTML=`<button class="close" data-action="close-dialog" aria-label="Close game settings">${I('x')}</button><h2>Make it feel right.</h2><p>Choose your game feedback.</p><div class="setting"><div><strong>Sound effects</strong><small>Short sounds after an answer.</small></div><button class="toggle" role="switch" aria-label="Game sound" aria-checked="${sound}" data-game="sound"></button></div><div class="setting"><div><strong>Gentle vibration</strong><small>On supported devices. Some browsers, including iPhone Safari, do not offer web vibration.</small></div><button class="toggle" role="switch" aria-label="Game vibration" aria-checked="${haptics}" data-game="haptics"></button></div>`;d.showModal();return true}
 if(a==='sound'||a==='haptics'){if(a==='sound')sound=!sound;else haptics=!haptics;try{localStorage.setItem('zuno-game-'+a,(a==='sound'?sound:haptics)?'on':'off')}catch{}b.setAttribute('aria-checked',String(a==='sound'?sound:haptics));feedback(true);return true}if(!s)return true;
 if(a==='check'&&!s.checked&&s.selected!==null){s.checked=true;const good=s.selected===s.data.questions[s.index].correct;if(good)s.score++;feedback(good);ctx.render(false);document.querySelector('.game-feedback')?.scrollIntoView({block:'nearest',behavior:ctx.reduced()?'instant':'smooth'})}
 if(a==='next'&&s.checked){if(s.index===s.data.questions.length-1){saveResult(s.score===s.data.questions.length?3:s.score>=s.data.questions.length*.6?2:1)}else{s.index++;s.selected=null;s.checked=false;ctx.render(false);document.querySelector('.challenge-title')?.focus({preventScroll:true})}}
 if(a==='reset-rover'){s.program=[];s.rover=s.data.start;s.codeMessage='A fresh program. What will you try?';ctx.render(false)}if(a==='run-rover'){let pos=s.data.start,blocked=false;const size=s.data.size;for(const d of s.program){const next=pos+({up:-size,down:size,left:-1,right:1})[d];if(next<0||next>=size*size||d==='left'&&pos%size===0||d==='right'&&pos%size===size-1||s.data.blocked.includes(next)){blocked=true;break}pos=next} s.rover=pos;if(pos===s.data.goal&&!blocked){saveResult(s.program.length===s.data.target?3:s.program.length<=s.data.target+4?2:1)}else{s.codeMessage=blocked?'The rover found a block or an edge. Change your instructions, then run again.':'The rover finished here. Add or change steps to reach the star.';feedback(false);ctx.render(false)}}
 if(a==='replay'){session=null;ctx.render(false)}if(a==='turn-back'){s.flipped=[];ctx.render(false)}
 if(a==='place-word'){const entry=s.data.puzzle.entries.find(e=>`${e.number}${e.dir}`===s.active);const value=document.querySelector('#cross-answer')?.value.toUpperCase().replace(/[^A-Z]/g,'')||'';if(!entry||value.length!==entry.word.length){ctx.toast(`This word needs ${entry?.word.length||'the right number of'} letters.`);return true}for(let k=0;k<value.length;k++)s.entries[`${entry.x+(entry.dir==='a'?k:0)},${entry.y+(entry.dir==='d'?k:0)}`]=value[k];s.checked=false;ctx.render(false)}
 if(a==='hint'){const cell=s.data.puzzle.cells.find(c=>s.entries[`${c.x},${c.y}`]!==c.answer);if(cell){s.entries[`${cell.x},${cell.y}`]=cell.answer;s.hints++;s.hintMessage='One letter revealed. Use its crossings to work out the next word.';ctx.render(false)}else ctx.toast('All the letters are in place. Check your puzzle!')}
 if(a==='check-crossword'){if(s.data.puzzle.cells.every(c=>s.entries[`${c.x},${c.y}`]===c.answer))saveResult(s.hints===0?3:s.hints<=3?2:1);else{s.checked=true;feedback(false);ctx.render(false)}}return true}
export function handleGameInput(e){if(!session||!e.target.dataset.crossCell)return;session.entries[e.target.dataset.crossCell]=e.target.value.toUpperCase().replace(/[^A-Z]/g,'').slice(-1);e.target.value=session.entries[e.target.dataset.crossCell];session.checked=false}
document.addEventListener('keydown',e=>{if(e.target.id==='cross-answer'&&e.key==='Enter'){e.preventDefault();document.querySelector('[data-game="place-word"]')?.click()}if(e.target.dataset?.crossCell&&session?.data.kind==='crossword'){const [x,y]=e.target.dataset.crossCell.split(',').map(Number),d=({ArrowRight:[1,0],ArrowLeft:[-1,0],ArrowDown:[0,1],ArrowUp:[0,-1]})[e.key];if(d){e.preventDefault();let xx=x+d[0],yy=y+d[1];while(xx>=0&&yy>=0&&xx<session.data.puzzle.width&&yy<session.data.puzzle.height){const next=document.querySelector(`[data-cross-cell="${xx},${yy}"]`);if(next){next.focus();break}xx+=d[0];yy+=d[1]}}}});
